from h34 import *
M=mcq;F=tf;S=short;N=num
numberline('c3-nani-jumps.svg',15,25,1,[(15,22,'+7 in one jump'),(15,20,'+5'),(20,22,'+2')],'Adding 15 + 7 on a number line')
chapter(3,'maths','vacation-with-my-nani-maa','Vacation with My Nani Maa',
 ('A box of balushahi','Nandini and Chirag go to see their Nani Maa. Nandini has 7 balushahi in her box and Chirag has 5 in his. They carry sweets, magazines, story books and stamps for Nani Maa. Along the way they add and take away, count stamps and radishes, jump on number lines and solve magic puzzles.'),
 [('Adding and taking away sweets',['Nandini has 7 balushahi and Chirag has 5, so together they have 7 + 5 = 12 balushahi.','If Nandini eats 5 of her 7 balushahi, we take away to find what is left: 7 - 5 = 2.','Adding means joining groups, and taking away means finding what is left or what is missing.','A tens frame helps us see small sums: to find 6 + 8, fill 8 boxes and then 6 more, and notice a full ten and 4 extra, so the answer is 14.']),
  ('Jumping on a number line',['Nandini and Chirag have 15 stamps and get 7 more. We can find 15 + 7 by taking one jump of 7 or by breaking the jump into easier parts.','One way is 15 + 5 = 20 and then 20 + 2 = 22. Another way is to jump 10 to 25 and come back 3 steps, because 15 + 10 - 3 = 22.','Different jumps give the same answer, so we can choose the path that feels easiest to us.','The number line can start at any number, and the jumps may be drawn unequal. What matters is that we write each jump we take.','To subtract on the line we jump backward. To find 52 - 37, we can go back 37 or count up from 37 to 52 and see that the jumps add up to 15.']),
  ('Adding bigger numbers with bundles and boxes',['Nani Maa has 25 red radishes and 36 white radishes. We add 25 + 36 by making bundles of ten and loose sticks.','Two bundles and 5 sticks join three bundles and 6 sticks. That is 5 bundles and 11 sticks, and 11 sticks make another bundle with 1 left, so the total is 61 radishes.','Before we calculate we estimate. 25 is close to 30 and 36 is close to 40, so the answer should be near 70, and 61 is a sensible answer.','A box diagram shows the whole as one long box and the parts inside it. If a box holds 100 vegetables and 65 are tomatoes, the rest are carrots, so 100 - 65 = 35 carrots.']),
  ('Making a hundred and comparing',['Nandini picked 85 apples and Chirag picked 67. Since 85 + 20 is 105, we already know the total is more than 100. Exactly, 85 + 67 = 152.','To find who picked more, we compare the two boxes: 85 - 67 = 18, so Nandini picked 18 apples more.','Words like more, total and sum point to addition. Words like less, take away, difference and reduce point to subtraction.','The number grid from 1 to 100 helps us move: adding 10 moves one row up, and adding 1 moves one step to the right.']),
  ('Magic sums',['In a magic square of the numbers 1 to 9, every row, every column and both diagonals add up to the same number, 15.','In the square 2 7 6, 9 5 1, 4 3 8 the first row is 2 + 7 + 6 = 15 and the middle column is 7 + 5 + 3 = 15.','Puzzles with row and column totals teach us to use what we know to find what is missing.'])],
 [('Nandini and Chirag have 15 stamps and get 7 more. How many stamps do they have now?',[('We join the stamps, so we add: 15 + 7.','Getting more means addition.'),('Jump 5 to reach 20 and then 2 more to reach 22.','Breaking 7 into 5 and 2 makes the jump easy.'),('They have 22 stamps now.','Check: 22 - 7 = 15.')]),
  ('Nani Maa has 25 red radishes and 36 white radishes. How many radishes does she have?',[('Estimate first: 25 is near 30 and 36 is near 40, so about 70.','An estimate tells us what size of answer to expect.'),('Add the tens: 20 + 30 = 50. Add the ones: 5 + 6 = 11.','Splitting each number into tens and ones.'),('50 + 11 = 61 radishes.','61 is close to our estimate of 70.')]),
  ('A box has 100 vegetables. 65 are tomatoes. How many are carrots?',[('The whole is 100 and one part is 65, so we need the other part.','Draw a box diagram to see the parts.'),('Count up from 65 to 100: 5 more makes 70 and 30 more makes 100, so 35.','Or subtract: 100 - 65 = 35.'),('There are 35 carrots.','Check: 65 + 35 = 100.')])],
 ('Explain two different ways to find 48 + 25 on a number line.',['Break one number into tens and ones','Use a friendly jump such as 25 = 20 + 5','Both ways give 73','Write the jumps you take'],['The jumps have to be equal in length','There is only one correct way to jump']),
 ['We add to join groups and subtract to find what is left, how many more or the difference.','A number line lets us jump forward to add and backward to subtract, in any friendly steps.','Estimating first tells us whether an answer is sensible.','A box diagram shows the whole and its parts, which helps us choose the operation.','A magic square has all rows, columns and diagonals with the same sum.'],
 [M('1',1,'Nandini has 7 balushahi and Chirag has 5. How many do they have together?','12',[('11','Count again: 7 + 5 is 12'),('2','That is 7 - 5')],'7 + 5 = 12.'),
  M('2',1,'Which operation finds how many are left after some are eaten?','Subtraction',[('Addition','Addition joins groups'),('Counting only by tens','That does not find what is left')],'Taking away means subtract.'),
  N('3',1,'15 + 7 = ?',22,'15 + 5 = 20 and 20 + 2 = 22.',[(21,'You added 6, not 7'),(23,'You added 8, not 7')]),
  N('4',1,'52 - 37 = ?',15,'From 37 jump 3 to 40, then 10 to 50, then 2 to 52. 3 + 10 + 2 = 15.',[(25,'Check by adding 25 to 37: that is 62'),(14,'Count the jumps again')]),
  F('5',1,'In a magic square of 1 to 9, every row adds up to 15.',True,'In the square 2 7 6, 9 5 1, 4 3 8 each row adds to 15.'),
  N('6',2,'25 red and 36 white radishes. How many in all?',61,'25 + 36: 20 + 30 = 50 and 5 + 6 = 11, so 61.',[(51,'Do not forget to add the 11 from the ones'),(60,'Add the ones 5 + 6 = 11, not 10')]),
  N('7',2,'A box holds 100 vegetables. 65 are tomatoes. How many are carrots?',35,'100 - 65 = 35, or 65 + 35 = 100.',[(45,'65 + 45 is 110'),(25,'65 + 25 is only 90')]),
  M('8',2,'Is 85 + 67 more than 100 or less?','More than 100',[('Less than 100','85 + 20 is already 105'),('Exactly 100','85 + 15 would be 100, but 67 is more than 15')],'85 + 67 = 152, which is more than 100.'),
  N('9',2,'Nandini picked 85 apples and Chirag picked 67. How many more did Nandini pick?',18,'85 - 67 = 18.',[(152,'That is the sum, not the difference'),(28,'Count back from 85 again')]),
  S('10',2,'Which word means the same as sum?',['total','the total','add','addition'],'Sum and total both tell us the answer to adding.'),
  M('11',3,'Which magic-square row adds up to a different number: 2 7 6, 9 5 1, 4 3 8?','None, all rows add to 15',[('The first row','2 + 7 + 6 = 15'),('The last row','4 + 3 + 8 = 15')],'All the rows, columns and diagonals add to 15.'),
  N('12',3,'A frog starts at 7 and jumps forward by 10 three times. Where does it land last?',37,'7, 17, 27, 37.',[(27,'That is after two jumps'),(40,'Add 10 three times to 7, not to 10')])],
 svgs=[('c3-nani-jumps','A number line from 15 to 25 with jumps of 5 and 2 reaching 22','Two small jumps do the same work as one jump of 7.')],
 keep=['number line','estimate','total','sum'])
